import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Directory Structure","description":"A complete walkthrough of every directory and file in a LitePHP project — what lives where, what you own, and what the framework manages for you.","frontmatter":{"title":"Directory Structure","description":"A complete walkthrough of every directory and file in a LitePHP project — what lives where, what you own, and what the framework manages for you."},"headers":[],"relativePath":"directory-structure.md","filePath":"directory-structure.md"}'),i={name:"directory-structure.md"};function n(d,e,r,p,l,c){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h1><blockquote><p>A complete walkthrough of every directory and file in a LitePHP project — what lives where, what you own, and what the framework manages for you.</p></blockquote><h2 id="full-directory-tree" tabindex="-1">Full Directory Tree <a class="header-anchor" href="#full-directory-tree" aria-label="Permalink to &quot;Full Directory Tree&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── app/</span></span>
<span class="line"><span>│   ├── Controllers/       # HTTP controllers</span></span>
<span class="line"><span>│   ├── Models/            # ActiveRecord-style ORM models</span></span>
<span class="line"><span>│   ├── Services/          # Business logic service classes</span></span>
<span class="line"><span>│   ├── Middleware/        # Custom middleware</span></span>
<span class="line"><span>│   ├── Routes/            # Web routes</span></span>
<span class="line"><span>│   └── views/             # .lites template files</span></span>
<span class="line"><span>├── database/</span></span>
<span class="line"><span>│   ├── migrations/        # Schema migration files</span></span>
<span class="line"><span>│   ├── seeders/           # Database seeders</span></span>
<span class="line"><span>│   └── factories/         # Model factories</span></span>
<span class="line"><span>├── public/</span></span>
<span class="line"><span>│   └── index.php          # Front controller / entry point</span></span>
<span class="line"><span>├── storage/</span></span>
<span class="line"><span>│   ├── cache/             # Compiled views, route cache, file cache</span></span>
<span class="line"><span>│   ├── logs/              # Application logs</span></span>
<span class="line"><span>│   ├── framework/</span></span>
<span class="line"><span>│   │   └── sessions/      # PHP session files</span></span>
<span class="line"><span>│   └── uploads/           # User file uploads</span></span>
<span class="line"><span>├── node_modules/          # Frontend dependencies (don&#39;t modify)</span></span>
<span class="line"><span>├── vendor/                # LitePHP framework package (don&#39;t modify)</span></span>
<span class="line"><span>├── .env                   # Environment variables</span></span>
<span class="line"><span>├── .env.example           # Environment template</span></span>
<span class="line"><span>├── autoload.php           # PSR-4 class autoloader</span></span>
<span class="line"><span>├── composer.json</span></span>
<span class="line"><span>└── lite                   # CLI entry point</span></span></code></pre></div><h2 id="top-level-directories" tabindex="-1">Top-Level Directories <a class="header-anchor" href="#top-level-directories" aria-label="Permalink to &quot;Top-Level Directories&quot;">​</a></h2><h3 id="app" tabindex="-1"><code>app/</code> <a class="header-anchor" href="#app" aria-label="Permalink to &quot;\`app/\`&quot;">​</a></h3><p>Where you write all of your application code. The PSR-4 autoloader maps the <code>App\\</code> namespace root to this directory.</p><table tabindex="0"><thead><tr><th>Subdirectory</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Controllers/</code></td><td>Handles HTTP actions. Should be thin — parse request, delegate to a Service, return a Response.</td></tr><tr><td><code>Models/</code></td><td>ORM model classes. Each model maps to a database table. The default <code>User</code> model is referenced by <code>config/auth.php</code>.</td></tr><tr><td><code>Services/</code></td><td>Business logic classes.</td></tr><tr><td><code>Middleware/</code></td><td>Custom middleware classes. The Kernel auto-discovers any class carrying a <code>#[RegisterMiddleware]</code> attribute.</td></tr><tr><td><code>Routes/</code></td><td>Web and API route definitions. <code>web.php</code> passes through CSRF middleware automatically; <code>api.php</code> uses token or JWT auth.</td></tr><tr><td><code>views/</code></td><td>All <code>.lites</code> template files. <code>response()-&gt;view(&#39;posts.index&#39;)</code> renders <code>app/views/posts/index.lites</code>.</td></tr></tbody></table><h3 id="database" tabindex="-1"><code>database/</code> <a class="header-anchor" href="#database" aria-label="Permalink to &quot;\`database/\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Subdirectory</th><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>migrations/</code></td><td><code>php lite migrate</code></td><td>Schema migration files</td></tr><tr><td><code>seeders/</code></td><td><code>php lite db:seed</code></td><td>Database seeders</td></tr><tr><td><code>factories/</code></td><td>—</td><td>Fake data generators for tests</td></tr></tbody></table><h3 id="public" tabindex="-1"><code>public/</code> <a class="header-anchor" href="#public" aria-label="Permalink to &quot;\`public/\`&quot;">​</a></h3><p>The only directory exposed to the web. <code>index.php</code> is the single entry point: defines <code>APP_BASE_PATH</code>, requires <code>autoload.php</code>, then hands off to <code>Core/Bootstrap/app.php</code>.</p><blockquote><p><strong>Apache:</strong> Copy <code>.htaccess</code> from the framework&#39;s <code>storage/</code> example to <code>public/</code> to enable clean URLs.</p><p><strong>Nginx:</strong> Add <code>try_files $uri $uri/ /index.php?$query_string</code> to your server block.</p></blockquote><h3 id="storage" tabindex="-1"><code>storage/</code> <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;\`storage/\`&quot;">​</a></h3><p>Written to by the framework at runtime. Must be writable by your web server process.</p><table tabindex="0"><thead><tr><th>Subdirectory</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cache/</code></td><td>Compiled views (<code>cache/views/</code>), route cache (<code>cache/data/</code>), file-driver cache entries</td></tr><tr><td><code>logs/</code></td><td>Application logs. A new dated file (<code>app-YYYY-MM-DD.log</code>) is created each day</td></tr><tr><td><code>framework/sessions/</code></td><td>PHP session files, pointed to by <code>session_save_path()</code> during bootstrap</td></tr><tr><td><code>uploads/</code></td><td>Files uploaded by users via the built-in upload helpers</td></tr></tbody></table><h3 id="node-modules" tabindex="-1"><code>node_modules/</code> <a class="header-anchor" href="#node-modules" aria-label="Permalink to &quot;\`node_modules/\`&quot;">​</a></h3><p>Frontend dependencies managed by npm. <strong>Do not modify directly.</strong></p><h3 id="vendor" tabindex="-1"><code>vendor/</code> <a class="header-anchor" href="#vendor" aria-label="Permalink to &quot;\`vendor/\`&quot;">​</a></h3><p>The LitePHP framework package managed by Composer. <strong>Do not modify directly.</strong></p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><h3 id="autoload-php" tabindex="-1"><code>autoload.php</code> <a class="header-anchor" href="#autoload-php" aria-label="Permalink to &quot;\`autoload.php\`&quot;">​</a></h3><p>Custom PSR-4 autoloader registering two namespace prefixes:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$prefixMap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;Core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $frameworkRoot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">Core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;App</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $appRoot       </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h3 id="lite" tabindex="-1"><code>lite</code> <a class="header-anchor" href="#lite" aria-label="Permalink to &quot;\`lite\`&quot;">​</a></h3><p>The CLI entry point. Run with <code>php lite &lt;command&gt;</code> — a plain PHP script, no global install needed.</p>`,26)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
